mapper.select:
select permission_code
from tbl_member_permission
where member_number = #{memberNumber}

select member_number, member_id, member_password, member_name, member_rank, member_use, dept_number, team_number, vacation_count, carryover_count, TO_CHAR(carryover_expire_date, 'YYYY-MM-DD') as carryover_expire_date, TO_CHAR(employment_date, 'YYYY-MM-DD') as employment_date, reset_date from tbl_member where not member_rank = '관리자'
and team_number = #{teamNumber}
order by member_name collate "ko_KR.utf8"

select member_number, member_id, member_password, member_name, member_rank, member_use, tm.dept_number, tt.team_number, td.dept_name, tt.team_name,
       case when vacation_count is null then '입력필요' else vacation_count end as vacation_count, carryover_count, TO_CHAR(tm.carryover_expire_date, 'YYYY-MM-DD') as carryover_expire_date,
       TO_CHAR(tm.employment_date, 'YYYY-MM-DD') as employment_date, tm.reset_date
from tbl_member tm
join tbl_dept td
on tm.dept_number = td.dept_number
join tbl_team tt
on tm.team_number = tt.team_number


		and tm.dept_number = #{deptNumber}


		and tm.team_number = #{teamNumber}


		and member_name like concat('%', #{memberName}, '%')


		and member_use = #{memberUse}


order by member_number limit #{criteria.amount} offset #{criteria.skip}

select count(member_number)
from tbl_member


		and dept_number = #{deptNumber}


		and team_number = #{teamNumber}


		and member_name like concat('%', #{memberName}, '%')


		and member_use = #{memberUse}

mapper.update:
update tbl_member
set member_id = #{memberId}, member_name = #{memberName},
    member_rank = #{memberRank}, dept_number = #{deptNumber}, team_number = #{teamNumber}

	, employment_date = #{employmentDate}::date


	, reset_date = #{resetDate}


	, member_password = #{memberPassword}


	, vacation_count = #{vacationCount}


	, carryover_expire_date = #{carryoverExpireDate}::date


	, carryover_expire_date = NULL

where member_number = #{memberNumber}

update tbl_member
set vacation_count = #{vacationCount}
where member_number = #{memberNumber}

update tbl_member
set vacation_count = CAST(CAST(vacation_count AS NUMERIC) + #{delta} AS VARCHAR)
where member_number = #{memberNumber}

mapper.select:
SELECT CAST(vacation_count AS NUMERIC)
FROM tbl_member
WHERE member_number = #{memberNumber}

SELECT COALESCE(CAST(carryover_count AS NUMERIC), 0)
FROM tbl_member
WHERE member_number = #{memberNumber}

mapper.update:
update tbl_member
set carryover_count = #{carryoverCount}
where member_number = #{memberNumber}

update tbl_member
set carryover_count = CAST(CAST(carryover_count AS NUMERIC) + #{delta} AS VARCHAR)
where member_number = #{memberNumber}

update tbl_member
set carryover_expire_date = #{carryoverExpireDate}::date
where member_number = #{memberNumber}

update tbl_member
set member_use = #{memberUse}, dept_number = 0, team_number = 0
where member_number = #{memberNumber}

update tbl_member
set dept_number = 0, team_number = 0
where dept_number = #{deptNumber}

update tbl_member
set team_number = 0
where team_number = #{teamNumber}
